function jumpSearch(index){const count=panel.querySelector('#smm-search-count');if(!searchHits.length){if(count)count.textContent='0/0';return;}searchIndex=(index+searchHits.length)%searchHits.length;const card=searchHits[searchIndex];for(let p=card.parentElement;p&&p!==panel;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;card.scrollIntoView({block:'center',behavior:'smooth'});for(const c of searchHits)c.classList.toggle('smm-search-current',c===card);if(count)count.textContent=(searchIndex+1)+'/'+searchHits.length;}
async function nextBatch(){if(job||draft||batchRunning)throw Error('请先保存或丢弃当前草稿');if(!batchQueue.length)throw Error('没有后续批次');batchRunning=true;try{while(batchQueue.length){const b=batchQueue[0];batchProcessing=true;try{await summarize(b.start,b.end,b.temporary,null,1,b.hide);}finally{batchProcessing=false;}if(!draft)break;batchQueue.shift();const mode=settings.batchClassification;if(mode==='manual')break;const recent=b.end>=api.chat().length-1-Math.max(0,Number(settings.keepRecent));for(const m of draft.items){m.kind=m.suggestedKind||(recent?'short':'long');if(m.kind==='long'&&!m.keywords.length){notify('长期记忆未返回关键词，请核对分类后保存',true);return;}}if(mode==='mixed'&&draft.items.some(m=>(settings.batchManualKinds||['fixed']).includes(m.kind)))break;await approve();}await render();}finally{batchRunning=false;}}

function choiceDialog(title,options){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='smm-editor';d.innerHTML='<h3>'+h(title)+'</h3>'+options.map(([v,label])=>'<button type="button" data-choice="'+v+'">'+h(label)+'</button>').join('')+'<button data-choice="">取消</button>';document.body.append(d);let result=null;d.onclick=e=>{const b=e.target.closest('[data-choice]');if(b){result=b.dataset.choice||null;d.close();}};d.onclose=()=>{d.remove();resolve(result);};d.showModal();});}

